{"command":"cat > /tmp/script_harness.py << 'PY'
import subprocess, os, sys, time, select

def run_interactive(keys_sequence, cwd="/tmp/walktest2", args=[], env_extra={}, cols=80, rows=24, wait_after=0.3):
    env=dict(os.environ)
    env["TERM"]="xterm-256color"
    env.update(env_extra)
    # command inside script
    exe="/workspace/executable"
    argstr=" ".join(args)
    inner=f"stty cols {cols} rows {rows}; {exe} {argstr} > /tmp/out_script.txt"
    # use script -q -c inner /dev/null ; stdout is pty output to pipe
    proc=subprocess.Popen(["script","-q","-c",inner,"/dev/null"], cwd=cwd, env=env, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    out_chunks=[]
    def drain(timeout=0.5):
        data=b""
        end=time.time()+timeout
        while time.time()<end:
            r,_,_=select.select([proc.stdout],[],[],0.05)
            if r:
                chunk=os.read(proc.stdout.fileno(), 65536)
                if not chunk:
                    break
                data+=chunk
        out_chunks.append(data)
        return data
    print("initial:", repr(drain(0.8)))
    for k in keys_sequence:
        if isinstance(k,str): k=k.encode()
        print(f">>> send {k!r}")
        proc.stdin.write(k); proc.stdin.flush()
        print("resp:", repr(drain(0.6)))
    # try exit if still running
    if proc.poll() is None:
        try:
            proc.stdin.write(b'q'); proc.stdin.flush()
            print("final q resp:", repr(drain(0.6)))
        except Exception as e: print(e)
    try:
        proc.wait(timeout=2)
    except:
        proc.kill(); print("killed")
    print("exit", proc.returncode)
    try: print("outfile", repr(open("/tmp/out_script.txt","rb").read()))
    except Exception as e: print(e)
    return b"".join(out_chunks)

if __name__=="__main__":
    run_interactive([b'j',b'j',b'k',b'\x1b[B',b'\r'])
