{"command":"cat > /tmp/t_keys_fuzz.py << 'PY'
import sys,re,string; sys.path.insert(0,"/tmp")
from h2 import *
subprocess.run(["tmux","new-session","-d","-s","keepalive","sleep","10000"],capture_output=True)
def sel():
    for l in capture(True).splitlines():
        m=re.search(r"48;5;(?:99|196)m([^\x1b]*)\x1b",l)
        if m: return m.group(1).strip()
def state():
    ls=sorted(os.listdir("/tmp/walktest")) if os.path.exists("/tmp/walktest") else []
    return (capture().splitlines()[:10],sel(),out(),ls)
chars=string.ascii_lowercase+string.ascii_uppercase+string.digits+"!@#$%^&*()_+-=[]{};:'\",<.>/?`~\\| "
for ch in chars:
    make_tree(); start()
    before=state()
    # tmux send literal
    if ch==" ":
        send("Space")
    else:
        send_lit(ch)
    after=state()
    if after!=before:
        print(f"KEY {ch!r}: before sel={before[1]} after sel={after[1]} out={after[2]!r} filesdiff={set(before[3])^set(after[3])}")
        print(" screen:",after[0])
    # attempt clean exit: Escape/q unless already out; if editor opens with q first exits editor
    for _ in range(2):
        if "EXIT" in out(): break
        send("q",delay=0.08)
    kill()
