# ---------- Go filepath helpers ----------
def go_clean(p):
    if p == "":
        return "."
    rooted = p.startswith("/")
    parts = []
    for part in p.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if parts and parts[-1] != "..":
                parts.pop()
            elif not rooted:
                parts.append(part)
        else:
            parts.append(part)
    out = ("/" if rooted else "") + "/".join(parts)
    if out == "":
        return "/" if rooted else "."
    return out

def go_dir(p):
    p = go_clean(p)
    if p == "/":
        return "/"
    i = p.rfind("/")
    if i < 0:
        return "."
    if i == 0:
        return "/"
    return p[:i]

def go_join(a, b):
    if a == "":
        return go_clean(b)
    if b == "":
        return go_clean(a)
    if b.startswith("/"):
        # filepath.Join does not discard a (unlike posixpath.join)
        return go_clean(a + "/" + b)
    return go_clean(a + "/" + b)

def go_base(p):
    p2 = p.rstrip("/")
    if p2 == "":
        return "/"
    return p2.rsplit("/", 1)[-1]

def getwd_logical():
    try:
        physical = os.getcwd()
    except Exception:
        physical = "/"
    pwd_env = os.environ.get("PWD", "")
    if pwd_env and pwd_env.startswith("/"):
        try:
            s1 = os.stat(pwd_env)
            s2 = os.stat(".")
            if s1.st_dev == s2.st_dev and s1.st_ino == s2.st_ino:
                return go_clean(pwd_env)
        except Exception:
            pass
    return physical

def go_abs(p):
    if p.startswith("/"):
        return go_clean(p)
    return go_join(getwd_logical(), p)

def go_ext(name):
    base = name.rsplit("/", 1)[-1]
    i = base.rfind(".")
    if i < 0:
        return ""
    return base[i:]

# ---------- Go-ish panic output ----------
def panic_exit(message, stack):
    try:
        sys.stderr.write(f"panic: {message}\n\ngoroutine 1 [running]:\n{stack}")
        sys.stderr.flush()
    except Exception:
        pass
    raise SystemExit(2)

# ---------- display width ----------
def rune_width(ch):
    o = ord(ch)
    if o == 0:
        return 0
    if o < 32 or (0x7f <= o < 0xa0):
        return 0
    if unicodedata.combining(ch):
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
