    return 1

def display_width(s):
    # Strip ANSI CSI / OSC sequences for width purposes.
    s = re.sub(r"\x1b\[[0-9;?]*[A-Za-z]", "", s)
    s = re.sub(r"\x1b\][^\x07\x1b]*(?:\x07|\x1b\\)", "", s)
    return sum(rune_width(c) for c in s)

def truncate_width(s, maxw):
    if maxw <= 0:
        return ""
    out = []
    w = 0
    for c in s:
        cw = rune_width(c)
        if w + cw > maxw:
            break
        out.append(c)
        w += cw
    return "".join(out)

def truncate_width_left(s, maxw):
    """Keep the rightmost characters fitting in maxw (as for preview paths)."""
    if display_width(s) <= maxw:
        return s
    if maxw <= 0:
        return ""
    out = []
    w = 0
    for c in reversed(s):
        cw = rune_width(c)
        if w + cw > maxw:
            break
        out.append(c)
        w += cw
    return "".join(reversed(out))

def pad_right(s, width):
    return s + " " * max(0, width - display_width(s))

# ---------- colour handling (termenv/lipgloss-like) ----------
XTERM_16 = [
    (0,0,0),(205,0,0),(0,205,0),(205,205,0),(0,0,238),(205,0,205),(0,205,205),(229,229,229),
    (127,127,127),(255,0,0),(0,255,0),(255,255,0),(92,92,255),(255,0,255),(0,255,255),(255,255,255),
]

def xterm256_palette():
    pal = list(XTERM_16)
    levels = [0,95,135,175,215,255]
    for r in levels:
        for g in levels:
            for b in levels:
                pal.append((r,g,b))
    for i in range(24):
        v = 8 + 10*i
        pal.append((v,v,v))
    return pal

XTERM256 = xterm256_palette()

def nearest_idx(rgb, palette):
    best = 0
    bestd = None
    for i,(r,g,b) in enumerate(palette):
        d = (rgb[0]-r)**2 + (rgb[1]-g)**2 + (rgb[2]-b)**2
        if bestd is None or d < bestd:
            bestd = d; best = i
    return best

@dataclass
class Color:
    kind: str  # 'rgb' or 'num'
    rgb: tuple = None
    num: int = None

def parse_color(value):
    if value is None:
        return None
    if isinstance(value, Color):
        return value
    s = str(value)
    if s == "":
        return None
    if s.startswith("#"):
        h = s[1:]
        if len(h) == 3 and all(c in "0123456789abcdefABCDEF" for c in h):
            return Color('rgb', tuple(int(c+c,16) for c in h))
        if len(h) == 6 and all(c in "0123456789abcdefABCDEF" for c in h):
            return Color('rgb', (int(h[0:2],16), int(h[2:4],16), int(h[4:6],16)))
        if len(h) == 8 and all(c in "0123456789abcdefABCDEF" for c in h):
            return Color('rgb', (int(h[0:2],16), int(h[2:4],16), int(h[4:6],16)))
        return None
    if re.fullmatch(r"[0-9]+", s):
        n = int(s)
        if 0 <= n <= 255:
            return Color('num', num=n)
    return None

def color_to_rgb(c):
    if c.kind == 'rgb':
        return c.rgb
    return XTERM256[c.num]

def detect_profile(out_fd):
    try:
        if not os.isatty(out_fd):
            return "ascii"
    except Exception:
        return "ascii"
    colorterm = os.environ.get("COLORTERM", "")
    if colorterm != "":
        low = colorterm.lower()
        if low in ("truecolor", "24bit"):
            return "truecolor"
        return "ansi256"
    term = os.environ.get("TERM", "")
    if "256color" in term:
        return "ansi256"
    if "color" in term or "ansi" in term or term == "linux":
        return "ansi"
    return "ascii"

class Styler:
    def __init__(self, profile):
        self.profile = profile
        self.main_color_raw = os.environ["WALK_MAIN_COLOR"] if "WALK_MAIN_COLOR" in os.environ else "#825DF2"
    def _code(self, col, foreground=True):
        if col is None or self.profile == "ascii":
            return None
        c = parse_color(col) if not isinstance(col, Color) else col
        if c is None:
            return None
        if self.profile == "truecolor":
            if c.kind == 'num' and c.num < 16:
                base = 30 if foreground else 40
                if c.num >= 8:
                    return str(base + 60 + (c.num - 8))
                return str(base + c.num)
            r,g,b = color_to_rgb(c)
            return f"{38 if foreground else 48};2;{r};{g};{b}"
        if self.profile == "ansi256":
            if c.kind == 'num' and c.num < 16:
                base = 30 if foreground else 40
                if c.num >= 8:
                    return str(base + 60 + (c.num - 8))
                return str(base + c.num)
            idx = c.num if c.kind == 'num' else nearest_idx(c.rgb, XTERM256)
            return f"{38 if foreground else 48};5;{idx}"
        # ansi (16 colours)
        if c.kind == 'num' and c.num < 16:
            idx = c.num
        else:
            idx = nearest_idx(color_to_rgb(c), XTERM_16)
        base = 30 if foreground else 40
        if idx >= 8:
            return str(base + 60 + (idx - 8))
        return str(base + idx)
    def style(self, text, fg=None, bg=None):
        if self.profile == "ascii":
            return text
        codes = []
        fgc = self._code(fg, True) if fg is not None else None
        bgc = self._code(bg, False) if bg is not None else None
        if fgc: codes.append(fgc)
        if bgc: codes.append(bgc)
        if not codes:
            return text
        return "\x1b[" + ";".join(codes) + "m" + text + "\x1b[0m"
    def header(self, text):
        return self.style(text, fg="#FFFFFF", bg="#5C5C5C")
    def search(self, text):
        return self.style(text, fg="#FFFFFF", bg="#499F1C")
    def selected(self, text, marked=False):
        bg = "#FF0000" if marked else self.main_color_raw
        return self.style(text, fg="#FFFFFF", bg=bg)
    def status(self, text, red=False):
        return self.style(text, fg="#FFFFFF", bg=("#FF0000" if red else "#5C5C5C"))
    def border(self, text):
        return self.style(text, fg=self.main_color_raw)

