# ---------- terminal renderer (BubbleTea standard-renderer-like) ----------
def csi_up(n):
    if n <= 0:
        return ""
    if n == 1:
        return "\x1b[A"
    return f"\x1b[{n}A"

def csi_left(n):
    if n <= 1:
        return "\x1b[D"
    return f"\x1b[{n}D"

def get_winsize(fd):
    try:
        data = fcntl.ioctl(fd, termios.TIOCGWINSZ, struct.pack("HHHH", 0,0,0,0))
        rows, cols, _, _ = struct.unpack("HHHH", data)
        return cols, rows
    except Exception:
        return 0, 0

class Renderer:
    def __init__(self, out_fd, alt=False):
        self.out_fd = out_fd
        self.alt = alt
        self.width = 0
        self.height = 0
        w,h = get_winsize(out_fd)
        if w > 0:
            self.width = w
        if h > 0:
            self.height = h
        self.last_lines = []
        self.last_view = None
        self.lines_rendered = 0
        self.saved_lines_rendered = 0
        self.repaint = True
        self.started = False
    def write(self, s):
        if isinstance(s, str):
            b = s.encode("utf-8", "surrogateescape")
        else:
            b = s
        try:
            os.write(self.out_fd, b)
        except Exception:
            pass
    def start(self):
        self.started = True
        out = "\x1b[?25l"
        if self.alt:
            out += "\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l"
            self.saved_lines_rendered = 0
            self.lines_rendered = 0
        out += "\x1b[?2004h"
        self.write(out)
        self.repaint = True
    def stop_sequences(self):
        out = "\x1b[2K\r\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l"
        if self.alt:
            out += "\x1b[?1049l\x1b[?25h"
        return out
    def stop(self):
        self.write(self.stop_sequences())
        self.started = False
    def enter_alt(self):
        if self.alt:
            return
        self.write("\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l")
        self.saved_lines_rendered = self.lines_rendered
        self.alt = True
        self.lines_rendered = 0
        self.last_lines = []
        self.last_view = None
        self.repaint = True
    def exit_alt(self):
        if not self.alt:
            return
        self.write("\x1b[?1049l\x1b[?25l")
        self.alt = False
        self.lines_rendered = self.saved_lines_rendered
        self.last_view = None
        # last_lines are disregarded when repainting, but keep an
        # effective old count through lines_rendered.
        self.repaint = True
    def suspend(self):
        # Release terminal for an external process (editor).
        self.write(self.stop_sequences())
        self.started = False
    def resume(self):
        # Re-acquire terminal after an external process.
        out = "\x1b[?25l"
        if self.alt:
            out += "\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l"
            self.lines_rendered = 0
            self.last_lines = []
        out += "\x1b[?2004h"
        self.write(out)
        self.started = True
        self.last_view = None
        self.repaint = True
    def render(self, view, force=False):
        if not force and not self.repaint and view == self.last_view:
            return
        self._flush(view)
    def render_final(self, view):
        # BubbleTea renders the final view with a trailing blank line.
        self._flush(view + "\n")
    def _flush(self, view):
        new_lines_full = view.split("\n")
        new_lines = list(new_lines_full)
        # In alt-screen mode the renderer crops to the terminal height.
        if self.alt and self.height > 0 and len(new_lines) > self.height:
            new_lines = new_lines[:self.height]
        old_lines = self.last_lines
        old_effective = self.lines_rendered
        repaint = self.repaint
        buf = []
        if self.alt:
            buf.append("\x1b[H")
        else:
            if old_effective > 1:
                buf.append(csi_up(old_effective - 1))
        if repaint:
            buf.append("\r")
        for i, line in enumerate(new_lines):
            is_last = (i == len(new_lines) - 1)
            unchanged = (not repaint and i < len(old_lines) and old_lines[i] == line)
            if unchanged:
                if not is_last:
                    buf.append("\n")
            else:
                buf.append(line + "\x1b[K")
                if not is_last:
                    buf.append("\r\n")
        if old_effective > len(new_lines):
            buf.append("\x1b[J")
        if self.alt:
            buf.append(f"\x1b[{len(new_lines)};H")
        else:
            buf.append(csi_left(self.width))
        self.write("".join(buf))
        self.last_lines = new_lines
        self.last_view = view
        self.lines_rendered = len(new_lines)
        self.repaint = False

# ---------- key parsing (BubbleTea-like) ----------
@dataclass
class KeyEvent:
    string: str = ""
    kind: str = "special"   # runes, space, special
    runes: list = field(default_factory=list)
    alt: bool = False

class KeyParser:
    def __init__(self):
        self.buf = b""
        self.in_paste = False
        self.paste_buf = b""
    def feed(self, data):
        """Parse one read chunk; plain runes in a chunk are grouped."""
        events = []
        data = self.buf + data
        self.buf = b""
        i = 0
        n = len(data)
        while i < n:
            if self.in_paste:
                end = data.find(b"\x1b[201~", i)
                if end < 0:
                    self.paste_buf += data[i:]
                    i = n
                    break
                self.paste_buf += data[i:end]
                text = self.paste_buf.decode("utf-8", "surrogateescape")
                events.append(KeyEvent(string=text, kind="runes", runes=list(text)))
                self.paste_buf = b""
                self.in_paste = False
                i = end + 6
                continue
            b = data[i]
            if b == 0x1b:
                ev, consumed = self._parse_escape(data, i)
                if consumed == 0:
                    self.buf = data[i:]
                    break
                if ev == "PASTE_START":
                    self.in_paste = True
                elif ev is not None:
                    events.append(ev)
                i += consumed
                continue
            if b in (0x0d, 0x0a, 0x09, 0x7f, 0x08) or b < 0x20:
                events.append(self._control_event(b))
                i += 1
                continue
            # Gather a run of printable runes from this chunk.
            j = i
            text_parts = []
            while j < n:
                bb = data[j]
                if bb == 0x1b or bb < 0x20 or bb == 0x7f:
                    break
                # decode one utf-8 rune (or a lone byte)
                start = j
                # Determine sequence length
                if bb < 0x80:
                    j += 1
                    text_parts.append(chr(bb))
                else:
                    # try decode up to 4 bytes
                    decoded = None
                    for ln in range(2,5):
                        if j+ln <= n:
                            try:
                                decoded = data[j:j+ln].decode("utf-8")
                                j += ln
                                break
                            except Exception:
                                decoded = None
                    if decoded is None:
                        # incomplete sequence: if at chunk end, buffer it
                        if j+4 > n and n-j < 4:
                            # could be incomplete, save rest
                            # but only if the bytes look like a valid prefix
                            self.buf = data[j:]
                            j = n
                            break
                        # invalid byte, consume one
                        text_parts.append(data[j:j+1].decode("utf-8","surrogateescape"))
                        j += 1
                    else:
                        text_parts.append(decoded)
            text = "".join(text_parts)
            if text == " ":
                events.append(KeyEvent(string=" ", kind="space", runes=[" "]))
            elif text:
                events.append(KeyEvent(string=text, kind="runes", runes=list(text)))
            i = j
            if self.buf:
                break
        return events
    def _control_event(self, b):
        if b == 0x0d:
            return KeyEvent(string="enter")
        if b == 0x0a:
            return KeyEvent(string="ctrl+j")
        if b == 0x09:
            return KeyEvent(string="tab")
        if b == 0x7f:
            return KeyEvent(string="backspace")
        if b == 0x08:
            return KeyEvent(string="ctrl+h")
        if b == 0x00:
            return KeyEvent(string="ctrl+space")
        if 0x01 <= b <= 0x1a:
            return KeyEvent(string="ctrl+" + chr(ord('a')+b-1))
        if b == 0x1c:
            return KeyEvent(string="ctrl+\\")
        if b == 0x1d:
            return KeyEvent(string="ctrl+]")
        if b == 0x1e:
            return KeyEvent(string="ctrl+^")
        if b == 0x1f:
            return KeyEvent(string="ctrl+_")
        return KeyEvent(string="")
    def _parse_escape(self, data, i):
        n = len(data)
        if i+1 >= n:
            return KeyEvent(string="esc"), 1
        c = data[i+1]
