def csi_up(n):
    if n <= 0:
        return ""
    if n == 1:
        return "\x1b[A"
    return f"\x1b[{n}A"

def csi_left(n):
    if n <= 1:
        return "\x1b[D"
    return f"\x1b[{n}D"

def get_winsize(fd):
    try:
        data = fcntl.ioctl(fd, termios.TIOCGWINSZ, struct.pack("HHHH", 0,0,0,0))
        rows, cols, _, _ = struct.unpack("HHHH", data)
        return cols, rows
    except Exception:
        return 0, 0

class Renderer:
    def __init__(self, out_fd, alt=False):
        self.out_fd = out_fd
        self.alt = alt
        self.width = 0
        self.height = 0
        w,h = get_winsize(out_fd)
        if w > 0:
            self.width = w
        if h > 0:
            self.height = h
        self.last_lines = []
        self.last_view = None
        self.lines_rendered = 0
        self.saved_lines_rendered = 0
        self.repaint = True
        self.started = False
    def write(self, s):
        if isinstance(s, str):
            b = s.encode("utf-8", "surrogateescape")
        else:
            b = s
        try:
            os.write(self.out_fd, b)
        except Exception:
            pass
