        self.started = True
        out = "\x1b[?25l"
        if self.alt:
            out += "\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l"
            self.saved_lines_rendered = 0
            self.lines_rendered = 0
        out += "\x1b[?2004h"
        self.write(out)
        self.repaint = True
