    def enter_alt(self):
        if self.alt:
            return
        self.write("\x1b[?1049h\x1b[2J\x1b[H\x1b[?25l")
        self.saved_lines_rendered = self.lines_rendered
        self.alt = True
        self.lines_rendered = 0
        self.last_lines = []
        self.last_view = None
        self.repaint = True
    def exit_alt(self):
        if not self.alt:
            return
        self.write("\x1b[?1049l\x1b[?25l")
        self.alt = False
        self.lines_rendered = self.saved_lines_rendered
        self.last_view = None
