def _tok_desc(tok):
    if tok.kind=="eof": return "EOF"
    if tok.kind=="op":
        if tok.val in "[](){}": return f'Bracket("{tok.val}")'
        return f'Operator("{tok.val}")'
    if tok.kind=="name": return f'Name("{tok.val}")'
    if tok.kind=="str": return f'String("{tok.val}")'
    if tok.kind in ("int","float"): return f'Number("{tok.text}")'
    if tok.kind=="pointer": return 'Pointer("#")'
    return tok.kind

