    def isname(self, v=None): return self.cur().kind=="name" and (v is None or self.cur().val==v)
    def take(self):
        t=self.cur(); self.pos+=1; return t
    def expect_op(self, v):
        if not self.isop(v):
            t=self.cur()
            if t.kind=="eof":
                raise ExprCompileError("unexpected token EOF", t.line, None, self.src)
            raise ExprCompileError(f"unexpected token {_tok_desc(t)}", t.line, t.col, self.src)
        return self.take()
    def err_unexpected(self, t=None):
        t=t or self.cur()
        if t.kind=="eof":
            # Empty source produces exactly this (no location).
            if self.src.strip()=="":
                raise ExprCompileError("unexpected token EOF", 1, None, self.src)
            raise ExprCompileError("unexpected token EOF", t.line, t.col, self.src)
        raise ExprCompileError(f"unexpected token {_tok_desc(t)}", t.line, t.col, self.src)
    def parse(self):
        if self.cur().kind=="eof":
            raise ExprCompileError("unexpected token EOF", 1, None, self.src)
        node=self.parse_expr()
        if self.cur().kind!="eof":
            # semicolons may separate statements at top level in expr? handled in ternary chain
            self.err_unexpected()
        return node
