        stack = f"main.compile({{0xc00001a058, 0x{len(src.encode()):x}}})\n\t/workspace/status_bar.go:16 +0xc5\nmain.main()\n\t/workspace/main.go:71 +0x127\n"
        panic_exit(txt.rstrip("\n"), stack)

