def expr_infer(node, scope):
    kind=node[0]
    if kind=="lit": return node[4]
    if kind=="arr": return "array"
    if kind=="map": return "map"
    if kind=="var":
        name=node[3]
        for s in reversed(scope):
            if name in s: return s[name]
        return {"current_file":"file","files":"files","$env":"any"}.get(name,"any")
    if kind=="pointer": return "any"
    if kind=="call":
        callee=node[3]
        if callee[0]=="var":
            sig=_EXPR_FUNCS.get(callee[3])
            if sig: return sig[2]
        return "any"
    if kind=="pipecall":
        return expr_infer(node[3], scope)
    if kind=="method":
        return {"Name":"string","IsDir":"bool","Size":"int"}.get(node[4],"any")
    if kind=="bin":
        op=node[3]
        if op in ("==","!=","<","<=",">",">=","in","not in","contains","startsWith","endsWith","and","or"): return "bool"
        if op=="..": return "array"
        lt=expr_infer(node[4],scope); rt=expr_infer(node[5],scope)
        if op=="+" and (lt=="string" or rt=="string"): return "string"
        if lt=="float" or rt=="float" or op=="/": return "float"
        if lt=="int" and rt=="int": return "int"
        return "any"
    if kind=="un": return "bool" if node[3] in ("!","not") else expr_infer(node[4],scope)
    if kind=="ternary": return expr_infer(node[4],scope)
    if kind=="index":
        base=expr_infer(node[3],scope)
        if base=="files": return "file"
        return "any"
    return "any"

def expr_validate(node, scope, source, in_closure=0):
    kind=node[0]
    def unknown(name,line,col):
        raise ExprCompileError(f"unknown name {name}", line,col,source)
    if kind=="lit": return
    if kind=="arr":
        for e in node[3]: expr_validate(e,scope,source,in_closure)
        return
    if kind=="map":
        for k,v in node[3]: expr_validate(v,scope,source,in_closure)
        return
    if kind=="closure":
        expr_validate(node[3],scope,source,in_closure+1); return
    if kind=="pointer":
        nm=node[3]
        if in_closure==0 and nm in ("",):
            raise ExprCompileError("cannot use pointer accessor outside closure", node[1],node[2],source)
        if nm not in ("","acc"):
            # #foo is not valid in expr-lang
            raise ExprCompileError("cannot use pointer accessor outside closure", node[1],node[2],source)
        return
    if kind=="var":
        name=node[3]
        for s in reversed(scope):
            if name in s: return
        if name in ("current_file","files","$env","$acc"): return
        unknown(name,node[1],node[2])
    if kind=="let":
        expr_validate(node[4],scope,source,in_closure)
        scope.append({node[3]: expr_infer(node[4],scope)})
        expr_validate(node[5],scope,source,in_closure)
        scope.pop(); return
    if kind=="call":
        callee=node[3]; args=node[4]
        fname=None
        if callee[0]=="var":
            fname=callee[3]
            if fname not in _EXPR_FUNCS:
                # could be a let-bound variable holding a function (unlikely)
                found=False
                for s in reversed(scope):
                    if fname in s: found=True
                if not found:
                    unknown(fname,callee[1],callee[2])
            else:
                mn,mx,_rt=_EXPR_FUNCS[fname]
                if len(args)<mn:
                    raise ExprCompileError(f"not enough arguments to call {fname}", callee[1],callee[2],source)
                if mx is not None and len(args)>mx:
                    raise ExprCompileError(f"too many arguments to call {fname}", callee[1],callee[2],source)
                if fname in ("PadLeft","PadRight") and len(args)==2:
                    t0=expr_infer(args[0],scope); t1=expr_infer(args[1],scope)
                    if t0 not in ("string","any","file"):
                        raise ExprCompileError(f"cannot use {t0} as argument (type string) to call {fname} ", args[0][1],args[0][2],source)
                    if t1 not in ("int","any"):
                        raise ExprCompileError(f"cannot use {t1} as argument (type int) to call {fname} ", args[1][1],args[1][2],source)
        else:
            expr_validate(callee,scope,source,in_closure)
        # closure arguments get pointer scope
        for idx,a in enumerate(args):
            inc=in_closure
            if fname in _CLOSURE_FUNCS and idx>=1:
                inc=in_closure+1
            expr_validate(a,scope,source,inc)
        return
    if kind=="pipecall":
        # node: call node with the piped value added as first arg at eval time
        expr_validate(node[4],scope,source,in_closure)
        call=node[3]
        # Validate call with an augmented arg count: rebuild a check manually
        callee=call[3]; args=call[4]
        if callee[0]=="var":
            fname=callee[3]
            if fname not in _EXPR_FUNCS:
                unknown(fname,callee[1],callee[2])
            mn,mx,_rt=_EXPR_FUNCS[fname]
            total=len(args)+1
            if total<mn:
                raise ExprCompileError(f"not enough arguments to call {fname}", callee[1],callee[2],source)
            if mx is not None and total>mx:
                raise ExprCompileError(f"too many arguments to call {fname}", node[1],node[2],source)
            if fname in ("PadLeft","PadRight"):
                # piped value is argument 0
                t0=expr_infer(node[4],scope)
                if t0 not in ("string","any","file"):
                    raise ExprCompileError(f"cannot use {t0} as argument (type string) to call {fname} ", node[4][1],node[4][2],source)
                if args:
                    t1=expr_infer(args[0],scope)
                    if t1 not in ("int","any"):
                        raise ExprCompileError(f"cannot use {t1} as argument (type int) to call {fname} ", args[0][1],args[0][2],source)
            for idx,a in enumerate(args):
                inc=in_closure+1 if fname in _CLOSURE_FUNCS else in_closure
                expr_validate(a,scope,source,inc)
        else:
            expr_validate(call,scope,source,in_closure)
        return
    if kind=="method":
        expr_validate(node[3],scope,source,in_closure)
        # Validate method names on known file objects lightly.
        base_t=expr_infer(node[3],scope)
        if base_t in ("file",) and node[4] not in ("Name","IsDir","Type","Info"):
            raise ExprCompileError(f"unknown name {node[4]}", node[1],node[2],source)
        for a in node[5]: expr_validate(a,scope,source,in_closure)
        return
    if kind=="member":
        expr_validate(node[3],scope,source,in_closure); return
    if kind=="index":
        base_t=expr_infer(node[3],scope)
        if base_t=="string":
            raise ExprCompileError("type string[int] is undefined", node[1],node[2],source)
        expr_validate(node[3],scope,source,in_closure); expr_validate(node[4],scope,source,in_closure); return
    if kind=="slice":
        expr_validate(node[3],scope,source,in_closure)
        if node[4] is not None: expr_validate(node[4],scope,source,in_closure)
        if node[5] is not None: expr_validate(node[5],scope,source,in_closure)
        return
    if kind=="bin":
        expr_validate(node[4],scope,source,in_closure); expr_validate(node[5],scope,source,in_closure); return
    if kind=="un":
        expr_validate(node[4],scope,source,in_closure); return
    if kind=="ternary":
        expr_validate(node[3],scope,source,in_closure); expr_validate(node[4],scope,source,in_closure); expr_validate(node[5],scope,source,in_closure); return

