class EvalCtx:
    def __init__(self, env_vars, funcs):
        self.vars = env_vars  # current_file, files, $env
        self.funcs = funcs
        self.scopes = []      # let scopes (dicts)
        self.pointers = []    # stack of ('#' value, 'acc' value)
    def lookup(self, name):
        for s in reversed(self.scopes):
            if name in s: return s[name]
        if name in self.vars: return self.vars[name]
        raise ExprRuntimeError(f"unknown name {name}")

