def builtin_call(fname, args, ctx):
    a = args
    if fname=="len":
        v=a[0]
        if v is None: return 0
        try: return len(v)
        except Exception: raise ExprRuntimeError("invalid len")
    if fname=="type":
        v=a[0]
        if isinstance(v,bool): return "bool"
        if isinstance(v,int): return "int"
        if isinstance(v,float): return "float"
        if isinstance(v,str): return "string"
        if isinstance(v,list): return "array"
        if isinstance(v,dict): return "map"
        if v is None: return "nil"
        return "unknown"
    if fname=="kind":
        return builtin_call("type",a,ctx)
    if fname=="string":
        v=a[0]
        if isinstance(v,list) and all(isinstance(x,int) and not isinstance(x,bool) for x in v):
            return "".join(chr(x) for x in v if 0<=x<0x110000)
        return go_v(v)
    if fname=="int":
        v=a[0]
        if isinstance(v,bool): return 1 if v else 0
        if isinstance(v,(int,float)): return int(v)
        if isinstance(v,str):
            try: return int(float(v)) if ("." in v or "e" in v or "E" in v) else int(v)
            except Exception: return 0
        return 0
    if fname=="float":
        v=a[0]
        if isinstance(v,(int,float)) and not isinstance(v,bool): return float(v)
        if isinstance(v,str):
            try: return float(v)
            except Exception: return 0.0
        return 0.0
    if fname=="abs": return abs(a[0])
    if fname=="ceil": return float(math.ceil(float(a[0])))
    if fname=="floor": return float(math.floor(float(a[0])))
    if fname=="round": return float(round(float(a[0])))
    if fname=="min" or fname=="max":
        vals=[]
        for x in a:
            if isinstance(x,list): vals.extend(x)
            else: vals.append(x)
        return (min if fname=="min" else max)(vals) if vals else None
    if fname=="sum":
        vals=[]
        for x in a:
            if isinstance(x,list): vals.extend(x)
            else: vals.append(x)
        return sum(vals)
    if fname=="trim":
        s=str(a[0]); cut=str(a[1]) if len(a)>1 else None
        return s.strip(cut) if cut else s.strip()
    if fname=="trimPrefix":
        s=str(a[0]); p=str(a[1]); return s[len(p):] if s.startswith(p) else s
    if fname=="trimSuffix":
        s=str(a[0]); p=str(a[1]); return s[:-len(p)] if p and s.endswith(p) else s
    if fname=="upper": return str(a[0]).upper()
    if fname=="lower": return str(a[0]).lower()
    if fname=="repeat": return str(a[0]) * int(a[1])
    if fname=="split":
        s=str(a[0])
        if len(a)<2: return s.split()
        sep=str(a[1])
        return s.split(sep) if sep else list(s)
    if fname=="splitAfter":
        s=str(a[0]); sep=str(a[1]) if len(a)>1 else ""
        if not sep: return list(s)
        parts=s.split(sep)
        return [p+sep for p in parts[:-1]] + ([parts[-1]] if parts[-1] else [])
    if fname=="join":
        if len(a)==1:
            xs=a[0]; sep=""
        elif len(a)>=2:
            if isinstance(a[0],list): xs=a[0]; sep=go_v(a[1])
            elif isinstance(a[1],list): xs=a[1]; sep=go_v(a[0])
            else: xs=a; sep=""
        else:
            xs=[]; sep=""
        if not isinstance(xs,list): xs=[xs]
        return sep.join(go_v(x) for x in xs)
    if fname=="concat":
        out=[]
        for x in a:
            if isinstance(x,list): out.extend(x)
            else: out.append(x)
        return out
    if fname=="keys":
        return sorted(a[0].keys(), key=lambda k: go_v(k)) if isinstance(a[0],dict) else []
    if fname=="values":
        if isinstance(a[0],dict):
            return [a[0][k] for k in sorted(a[0].keys(), key=lambda k: go_v(k))]
        return []
    if fname=="sort":
        xs=a[0] if a and isinstance(a[0],list) else []
        try: return sorted(xs)
        except Exception: return sorted(xs, key=lambda x: go_v(x))
    if fname=="uniq":
        out=[]
        for x in (a[0] if a and isinstance(a[0],list) else []):
            if not any(_go_equals(x,y) for y in out): out.append(x)
