        return _member(eval_expr(node[3],ctx), node[4])
    if kind=="method":
        obj=eval_expr(node[3],ctx)
        args=[eval_expr(a,ctx) for a in node[5]]
        return _method(obj,node[4],args,ctx)
    if kind=="index":
        obj=eval_expr(node[3],ctx); idx=eval_expr(node[4],ctx)
