            if not isinstance(idx,int) or isinstance(idx,bool):
                raise ExprRuntimeError("index must be int")
            # Go panics on out-of-range
            if idx<0 or idx>=len(obj):
                raise ExprRuntimeError(f"index out of range [{idx}] with length {len(obj)}")
            return obj[idx]
        if isinstance(obj,dict):
            return obj.get(idx)
        raise ExprRuntimeError("cannot index")
    if kind=="slice":
        obj=eval_expr(node[3],ctx)
        lo=eval_expr(node[4],ctx) if node[4] is not None else None
        hi=eval_expr(node[5],ctx) if node[5] is not None else None
        if isinstance(obj,(list,str)):
            return obj[lo:hi]
        raise ExprRuntimeError("cannot slice")
    if kind=="un":
        op=node[3]; v=eval_expr(node[4],ctx)
        if op in ("!","not"): return not _go_truthy(v)
        if op=="-":
            if _is_num(v): return -v
            raise ExprRuntimeError("invalid unary -")
        if op=="+": return v
        return v
    if kind=="ternary":
        return eval_expr(node[4],ctx) if _go_truthy(eval_expr(node[3],ctx)) else eval_expr(node[5],ctx)
    if kind=="bin":
        op=node[3]
        if op=="and":
            return _go_truthy(eval_expr(node[4],ctx)) and _go_truthy(eval_expr(node[5],ctx))
        if op=="or":
            return _go_truthy(eval_expr(node[4],ctx)) or _go_truthy(eval_expr(node[5],ctx))
        a=eval_expr(node[4],ctx); b=eval_expr(node[5],ctx)
        if op=="==": return _go_equals(a,b)
