                return a - q*b
            raise ExprRuntimeError("invalid %")
        if op=="**":
            if _is_num(a) and _is_num(b): return float(a)**float(b)
            raise ExprRuntimeError("invalid **")
        raise ExprRuntimeError(f"unknown operator {op}")
    if kind=="call":
        callee=node[3]
        if callee[0]!="var":
            raise ExprRuntimeError("call of non-function")
        fname=callee[3]
        argnodes=node[4]
