class EvalCtx:
    def __init__(self, env_vars, funcs):
        self.vars = env_vars  # current_file, files, $env
        self.funcs = funcs
        self.scopes = []      # let scopes (dicts)
        self.pointers = []    # stack of ('#' value, 'acc' value)
    def lookup(self, name):
        for s in reversed(self.scopes):
            if name in s: return s[name]
        if name in self.vars: return self.vars[name]
        raise ExprRuntimeError(f"unknown name {name}")

def _is_num(v): return isinstance(v,(int,float)) and not isinstance(v,bool)

def _go_truthy(v):
    # expr-lang requires bool in conditions, but be lenient.
    return bool(v)

def _go_equals(a,b):
    if _is_num(a) and _is_num(b):
        return float(a)==float(b)
    if isinstance(a,bool) or isinstance(b,bool):
        return a is b
    return a==b

def _member(obj, name):
    if obj is None:
        raise ExprRuntimeError("cannot access member of nil")
    if isinstance(obj, dict):
        if name in obj: return obj[name]
        return None
    # Env / entry objects expose expr_member
    m = getattr(obj, "expr_member", None)
    if callable(m):
        return m(name)
    if hasattr(obj, name):
        v = getattr(obj, name)
        return v
    # Case variants
    for cand in (name, name[:1].upper()+name[1:], name[:1].lower()+name[1:]):
        if hasattr(obj, cand):
            return getattr(obj,cand)
    raise ExprRuntimeError(f"unknown member {name}")

def _method(obj, name, args, ctx):
    if obj is None:
        raise ExprRuntimeError("cannot call method on nil")
    m = getattr(obj, "expr_method", None)
    if callable(m):
        return m(name, args)
    # strings / lists have a few expr methods? Not in expr-lang; ignore.
    if hasattr(obj, name) and callable(getattr(obj,name)):
        return getattr(obj,name)(*args)
    raise ExprRuntimeError(f"unknown method {name}")

