def call_function(fname, argnodes, ctx, piped):
    # Closure builtins receive unevaluated predicate nodes.
    if fname in ("filter","map","all","any","none","one","count","find","groupBy","sortBy"):
        vals=[]
        if not isinstance(piped,_NoPipe): vals.append(piped)
        # first non-closure args, last arg is predicate
        # Structure: (collection, predicate)
        coll = vals[0] if vals else eval_expr(argnodes[0],ctx)
        pred_node = argnodes[-1] if argnodes else None
        if pred_node is None:
            raise ExprRuntimeError(f"{fname} requires a predicate")
        # If piped, first explicit arg is predicate; if not, second.
        if isinstance(coll, dict):
            items=list(coll.values())
        elif isinstance(coll, list):
            items=coll
        elif coll is None:
            items=[]
        else:
            items=[coll]
        def apply_pred(x, acc=None):
            ctx.pointers.append((x,acc))
            try: return eval_expr(pred_node,ctx)
            finally: ctx.pointers.pop()
        if fname=="filter": return [x for x in items if _go_truthy(apply_pred(x))]
        if fname=="map": return [apply_pred(x) for x in items]
        if fname=="all": return all(_go_truthy(apply_pred(x)) for x in items)
        if fname=="any": return any(_go_truthy(apply_pred(x)) for x in items)
        if fname=="none": return not any(_go_truthy(apply_pred(x)) for x in items)
        if fname=="one": return sum(1 for x in items if _go_truthy(apply_pred(x)))==1
        if fname=="count": return sum(1 for x in items if _go_truthy(apply_pred(x)))
        if fname=="find":
            for x in items:
                if _go_truthy(apply_pred(x)): return x
            return None
        if fname=="groupBy":
            out={}
            for x in items:
                k=apply_pred(x)
                out.setdefault(k,[]).append(x)
            return out
        if fname=="sortBy":
            return sorted(items, key=lambda x: apply_pred(x))
    if fname=="reduce":
        if not isinstance(piped,_NoPipe):
            coll=piped; pred_node=argnodes[0]; acc=eval_expr(argnodes[1],ctx) if len(argnodes)>1 else None
        else:
            coll=eval_expr(argnodes[0],ctx); pred_node=argnodes[1]; acc=eval_expr(argnodes[2],ctx) if len(argnodes)>2 else None
        items=coll if isinstance(coll,list) else []
        for x in items:
            ctx.pointers.append((x,acc))
            try: acc=eval_expr(pred_node,ctx)
            finally: ctx.pointers.pop()
        return acc
