# ---------- filesystem / entries ----------
def go_errno(e):
    s = getattr(e, 'strerror', None) or str(e)
    return s[:1].lower() + s[1:] if s else str(e)

def go_filemode_string(st_mode, type_only=False):
    letters = []
    if stat.S_ISDIR(st_mode): letters.append('d')
    if stat.S_ISLNK(st_mode): letters.append('L')
    if stat.S_ISBLK(st_mode) or stat.S_ISCHR(st_mode): letters.append('D')
    if stat.S_ISFIFO(st_mode): letters.append('p')
    if stat.S_ISSOCK(st_mode): letters.append('S')
    if not type_only and (st_mode & stat.S_ISUID): letters.append('u')
    if not type_only and (st_mode & stat.S_ISGID): letters.append('g')
    if stat.S_ISCHR(st_mode): letters.append('c')
    if not type_only and (st_mode & stat.S_ISVTX): letters.append('t')
    if not letters: letters.append('-')
    if type_only:
        perms = "---------"
    else:
        perms = "".join("rwx"[i%3] if (st_mode >> (8-i)) & 1 else "-" for i in range(9))
    return "".join(letters) + perms

def ls_mode_string(st_mode):
    if stat.S_ISDIR(st_mode): t='d'
    elif stat.S_ISLNK(st_mode): t='l'
    elif stat.S_ISFIFO(st_mode): t='p'
    elif stat.S_ISSOCK(st_mode): t='s'
    elif stat.S_ISBLK(st_mode): t='b'
    elif stat.S_ISCHR(st_mode): t='c'
    elif stat.S_ISREG(st_mode): t='-'
    else: t='?'
    chars=[t]
    for i in range(9):
        chars.append("rwx"[i%3] if (st_mode >> (8-i)) & 1 else "-")
    if st_mode & stat.S_ISUID: chars[3]='s'
    if st_mode & stat.S_ISGID: chars[6]='s'
    if st_mode & stat.S_ISVTX: chars[9]='t'
    return "".join(chars)

def human_size(n):
    if n < 1024:
        return f"{n}B"
    units="KMGTPE"
    div=1024; exp=0
    while n // div >= 1024 and exp < len(units)-1:
        div *= 1024; exp += 1
    # The reference behaves like the common ByteCount helper: it steps
    # while the scaled value still reaches the next unit.
    # Correct the exponent computation to match that helper exactly.
    div=1024; exp=0
    m=n//div
    while m >= 1024:
        div*=1024; exp+=1; m=n//div
    return f"{n/div:.1f}{units[exp]}B"

class GoFileModeValue:
    def __init__(self, st_mode, type_only=False):
        self.st_mode=st_mode; self.type_only=type_only
    def go_string(self):
        return go_filemode_string(self.st_mode, self.type_only)

class GoTimeValue:
    def __init__(self, mtime):
        self.mtime=mtime
    def go_string(self):
        lt=time.localtime(self.mtime)
        frac = self.mtime - math.floor(self.mtime)
        s=time.strftime("%Y-%m-%d %H:%M:%S", lt)
        if frac:
            s += f".{int(round(frac*1e9)):09d}".rstrip('0')
        s += time.strftime(" %z %Z", lt)
        return s

