        self._after_move()
    def move_up(self):
        if self.files:
            self.cursor=(self.cursor-1)%len(self.files)
        self._after_move()
    def move_right(self):
        if self.files:
            rows=max(1,self.rows); cols=math.ceil(len(self.files)/rows)
            col=self.cursor//rows; row=self.cursor%rows
            col=(col+1)%cols
            idx=col*rows+row
            if idx>=len(self.files): idx=len(self.files)-1
            self.cursor=idx
        self._after_move()
    def move_left(self):
        if self.files:
            rows=max(1,self.rows); cols=math.ceil(len(self.files)/rows)
            col=self.cursor//rows; row=self.cursor%rows
            col=(col-1)%cols
            idx=col*rows+row
            if idx>=len(self.files): idx=len(self.files)-1
            self.cursor=idx
        self._after_move()
    def move_col_start(self):
        if self.files:
            rows=max(1,self.rows); self.cursor=(self.cursor//rows)*rows
        self._after_move()
    def move_col_end(self):
        if self.files:
            rows=max(1,self.rows); self.cursor=min((self.cursor//rows+1)*rows, len(self.files))-1
        self._after_move()
    def move_row_start(self):
        if self.files:
            rows=max(1,self.rows); self.cursor=self.cursor%rows
        self._after_move()
    def move_row_end(self):
        if self.files:
            rows=max(1,self.rows); row=self.cursor%rows
            last_col=(len(self.files)-1)//rows
            idx=last_col*rows+row
            if idx>=len(self.files): idx=len(self.files)-1
            self.cursor=idx
        self._after_move()
    def move_home(self):
        self.cursor=0; self._after_move()
    def move_end(self):
        if self.files: self.cursor=len(self.files)-1
        self._after_move()
