    def press_delete(self):
        if not self.files:
            return
        if not self.mark_delete:
            self.mark_delete=True
            return
        self.mark_delete=False
        idx=self.cursor
        entry=self.files.pop(idx)
        self.pending.append(PendingDelete(entry=entry, dirpath=self.path, index=idx, count=5))
        if self.next_tick is None:
            self.next_tick=time.monotonic()+1.0
        self._clamp_cursor()
        self._recalc_rows()
        self.update_status()
    def press_undo(self):
        self.show_help=False
        if self.pending:
            top=self.pending.pop()
            if not self.pending:
                self.next_tick=None
            if top.dirpath==self.path:
                idx=min(top.index, len(self.files))
                self.files.insert(idx, top.entry)
                self.cursor=idx
                self._recalc_rows()
            self.mark_delete=False
            self.update_status()
        else:
            self.mark_delete=False
    def do_tick(self):
        if not self.pending:
            self.next_tick=None; return
        remaining=[]
        for p in self.pending:
            p.count-=1
            if p.count<0:
                self._actual_delete(p.entry.fullpath)
            else:
                remaining.append(p)
        self.pending=remaining
        if self.pending:
            self.next_tick=time.monotonic()+1.0
        else:
            self.next_tick=None
        self.update_status()
    def _actual_delete(self, path):
        if "WALK_REMOVE_CMD" in os.environ:
            cmd=os.environ["WALK_REMOVE_CMD"]
            try:
                subprocess.run([cmd, path], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                pass
            return
        try:
            stt=os.lstat(path)
            if stat.S_ISDIR(stt.st_mode):
                import shutil; shutil.rmtree(path)
            else:
                os.unlink(path)
        except Exception:
            pass
    def delete_all_pending(self):
        for p in self.pending:
            self._actual_delete(p.entry.fullpath)
        self.pending=[]
    # ----- misc actions -----
    def press_yank(self):
        cur=self.current()
        if cur is None:
            return
        path=cur.fullpath
        # xclip first, then xsel (atotto/clipboard order on Linux)
        import shutil
        try:
            if shutil.which("xclip"):
                subprocess.run(["xclip","-in","-selection","clipboard"], input=path.encode(), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            elif shutil.which("xsel"):
                subprocess.run(["xsel","--input","--clipboard"], input=path.encode(), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass
        self.status_text=f"copied: {path}"
        self.status_red=False

