# ---------- fuzzy scoring ----------
def _fuzzy_bonus(target, j):
    if j==0: return 8
    prev=target[j-1]; cur=target[j]
    if not prev.isalnum() and cur.isalnum(): return 8
    if prev.islower() and cur.isupper(): return 7
    if prev.isalpha() and cur.isdigit(): return 7
    return 0

def fuzzy_score(pattern, target):
    """fzf-style scoring; returns None if pattern is not a subsequence."""
    p=pattern.lower(); t=target.lower()
    if p=="": return 0
    # Quick subsequence check (case-insensitive).
    it=iter(t)
    for ch in p:
        found=False
        for tc in it:
            if tc==ch: found=True; break
        if not found: return None
    # DP over alignments.
    NEG=-10**9
    prev_row=None
    # We keep, per target position, the best score for matching the
    # pattern prefix ending exactly at that target position.
    for pi, pch in enumerate(p):
        row=[NEG]*len(t)
        best_before=NEG  # best prev_row score for positions < j, with gap handling
        # For gap penalties we track a running value: extending a gap
        # costs -1 per extra char after an initial -3 to open it.
        running=NEG
        for tj, tch in enumerate(t):
            if pi>0 and prev_row is not None:
                # candidate from any previous position
                if prev_row[tj-1] if tj>0 else NEG:
                    pass
                # running candidate: best prev score ending < tj,
                # penalised for the gap.
                if tj>0 and prev_row[tj-1]!=NEG:
                    # Start/extend gap bookkeeping: we maintain `running`
                    # as the best (prev score - gap cost to reach tj).
                    cand_start = prev_row[tj-1] - 3
                    if running==NEG:
                        running=cand_start
                    else:
                        running=max(running-1, cand_start)
            if tch!=pch:
                continue
            bonus=_fuzzy_bonus(target,tj)
            if pi==0:
                score=16 + bonus*2
                # leading gap penalty
                if tj>0:
                    score += -3 + (-1)*(tj-1)
                row[tj]=score
            else:
                best=NEG
                # consecutive
                if tj>0 and prev_row[tj-1]!=NEG:
                    b=max(bonus,4)
                    best=max(best, prev_row[tj-1]+16+b)
                # after a gap
                if running!=NEG:
                    # running already includes the -3 start (when the
                    # previous match was immediately before, that path is
                    # dominated by the consecutive candidate above).
                    best=max(best, running+16+bonus)
                row[tj]=best
        prev_row=row
    if prev_row is None: return 0
    best=NEG; bestpos=0
    for tj,v in enumerate(prev_row):
        if v>best: best=v; bestpos=tj
    if best==NEG: return None
    # Penalise trailing unmatched characters a little ( shorter /
    # more exact targets win for very short patterns ).
    best -= (len(t)-1-bestpos)
    return best

