    def _header_line(self, title=None, truncate_to=None):
        path_part=self.path if title is None else title
        search=self.search if self.fuzzy_on else ""
        if truncate_to is not None:
            combined=path_part+search
            trunc=truncate_width_left(combined, truncate_to)
            removed=len(combined)-len(trunc)
            # removed counted in characters; recompute against display
            # widths only matters for exotic names.
            if removed>=len(path_part):
                path_vis=""
                search_vis=trunc
            else:
                path_vis=path_part[removed:]
                search_vis=search
            return self.styler.header(path_vis)+self.styler.search(search_vis)
        return self.styler.header(path_part)+self.styler.search(search)
    def _grid_lines(self, entries, selected_idx):
        if not entries:
            return []
        names=[self.display_name(e) for e in entries]
        widths=[display_width(n) for n in names]
        if entries is self.files:
            rows=self.rows
        else:
            rows=compute_rows(len(entries), widths, self.width, self.height)
        if rows<=0: rows=1
        cols=math.ceil(len(entries)/rows)
        col_widths=[]
        for c in range(cols):
            seg=widths[c*rows:(c+1)*rows]
            col_widths.append(max(seg) if seg else 0)
        lines=[]
        for r in range(rows):
            cells=[]
            for c in range(cols):
                idx=c*rows+r
                if idx>=len(entries): continue
                text=names[idx]
                pad=" "*(col_widths[c]-display_width(text))
                if selected_idx is not None and idx==selected_idx:
                    cells.append(self.styler.selected(text+pad, marked=self.mark_delete))
                else:
                    cells.append(text+pad)
            lines.append("    ".join(cells))
        return lines
    def _body_lines(self):
        if self.err is not None:
            lines=box_lines(self.err)
        elif not self.files:
            lines=box_lines("No files")
        else:
            lines=self._grid_lines(self.files, self.cursor)
        if self.status_text!="":
            lines=lines+[self.styler.status(self.status_text, red=self.status_red)]
        return lines
    def view(self):
        if self.show_help:
            lines=[self._header_line(title="help"), ""] + HELP_KEY_LINES + ["",""]
            return "\n".join(lines)
        if self.preview_on:
            return "\n".join(self._preview_lines())
        lines=[self._header_line()] + self._body_lines()
        return "\n".join(lines)
    def _preview_lines(self):
        body=self._body_lines()
        left_width=max((display_width(l) for l in body), default=0)
        left=[self._header_line(truncate_to=left_width)] + body
        # recompute left width including header now (header truncated to it)
        left_width=max((display_width(l) for l in left), default=0)
        gap_w=3 if self.with_border else 2
        avail=max(0, self.width-left_width-gap_w) if self.width>0 else 10**9
        right=self._preview_right_lines(avail)
        right_width=max((display_width(l) for l in right), default=0)
        height=max(len(left),len(right))
        out=[]
        for i in range(height):
            l=left[i] if i<len(left) else ""
            lpad=l + " "*max(0,left_width-display_width(l))
            if self.with_border:
                if i<len(right):
                    r=right[i]
                    out.append(lpad+" "+self.styler.border("│")+" "+(r+" "*max(0,right_width-display_width(r))))
                else:
                    out.append(lpad+" "*(gap_w+right_width))
            else:
                r=right[i] if i<len(right) else ""
                out.append(lpad+"  "+(r+" "*max(0,right_width-display_width(r))))
        return out
    def _preview_right_lines(self, avail):
        cur=self.current()
        if cur is None:
            return [self.styler.header("")]
        title=self.styler.header(cur.name)
        path=cur.fullpath
        try:
            stt=os.stat(path)
        except OSError as e:
            return [title] + box_lines(f"stat {path}: {go_errno(e)}")
        if stat.S_ISDIR(stt.st_mode):
            entries,err=self.read_entries(path)
            if err is not None:
                return [title] + box_lines(err)
            if not entries:
                return [title] + box_lines("No files")
            return [title] + self._grid_lines(entries, None)
        # file preview: reading a FIFO blocks, exactly like the reference
        try:
            with open(path,'rb') as f:
                data=f.read()
        except OSError as e:
            return [title] + box_lines(f"open {path}: {go_errno(e)}")
        if b"\x00" in data:
            return [title] + box_lines("No preview available")
        text=data.decode("utf-8","surrogateescape")
        text=text.replace("\x1b","")
        lines=text.split("\n")
        if avail < 10**8:
            lines=[truncate_width(l, avail) for l in lines]
        return [title] + lines
    # ----- movement -----
    def _after_move(self):
        self.mark_delete=False
        self.update_status()
    def move_down(self):
        if self.files:
            self.cursor=(self.cursor+1)%len(self.files)
        self._after_move()
    def move_up(self):
        if self.files:
            self.cursor=(self.cursor-1)%len(self.files)
        self._after_move()
    def move_right(self):
        if self.files:
            rows=max(1,self.rows); cols=math.ceil(len(self.files)/rows)
            col=self.cursor//rows; row=self.cursor%rows
            col=(col+1)%cols
            idx=col*rows+row
            if idx>=len(self.files): idx=len(self.files)-1
            self.cursor=idx
        self._after_move()
    def move_left(self):
        if self.files:
            rows=max(1,self.rows); cols=math.ceil(len(self.files)/rows)
            col=self.cursor//rows; row=self.cursor%rows
            col=(col-1)%cols
            idx=col*rows+row
            if idx>=len(self.files): idx=len(self.files)-1
            self.cursor=idx
        self._after_move()
    def move_col_start(self):
        if self.files:
            rows=max(1,self.rows); self.cursor=(self.cursor//rows)*rows
        self._after_move()
    def move_col_end(self):
        if self.files:
            rows=max(1,self.rows); self.cursor=min((self.cursor//rows+1)*rows, len(self.files))-1
        self._after_move()
    def move_row_start(self):
        if self.files:
            rows=max(1,self.rows); self.cursor=self.cursor%rows
        self._after_move()
    def move_row_end(self):
        if self.files:
            rows=max(1,self.rows); row=self.cursor%rows
            last_col=(len(self.files)-1)//rows
            idx=last_col*rows+row
            if idx>=len(self.files): idx=len(self.files)-1
            self.cursor=idx
        self._after_move()
    def move_home(self):
        self.cursor=0; self._after_move()
    def move_end(self):
        if self.files: self.cursor=len(self.files)-1
        self._after_move()
    # ----- fuzzy -----
    def fuzzy_search(self):
        query=self.search[1:] if self.search.startswith("/") else self.search
        if query=="" or not self.files:
            return
        best=None; best_score=None
        for i,e in enumerate(self.files):
            s=fuzzy_score(query, e.name)
            if s is None: continue
            if best_score is None or s>=best_score:
                best_score=s; best=i
        if best is not None:
            if best!=self.cursor:
                self.mark_delete=False
            self.cursor=best
            self.update_status()
    # ----- deletion -----
    def press_delete(self):
        if not self.files:
            return
        if not self.mark_delete:
            self.mark_delete=True
            return
        self.mark_delete=False
        idx=self.cursor
        entry=self.files.pop(idx)
        self.pending.append(PendingDelete(entry=entry, dirpath=self.path, index=idx, count=5))
        if self.next_tick is None:
            self.next_tick=time.monotonic()+1.0
        self._clamp_cursor()
        self._recalc_rows()
        self.update_status()
    def press_undo(self):
        self.show_help=False
        if self.pending:
            top=self.pending.pop()
            if not self.pending:
                self.next_tick=None
            if top.dirpath==self.path:
                idx=min(top.index, len(self.files))
                self.files.insert(idx, top.entry)
                self.cursor=idx
                self._recalc_rows()
            self.mark_delete=False
            self.update_status()
        else:
            self.mark_delete=False
    def do_tick(self):
        if not self.pending:
            self.next_tick=None; return
        remaining=[]
        for p in self.pending:
            p.count-=1
            if p.count<0:
                self._actual_delete(p.entry.fullpath)
            else:
                remaining.append(p)
        self.pending=remaining
        if self.pending:
            self.next_tick=time.monotonic()+1.0
        else:
            self.next_tick=None
        self.update_status()
    def _actual_delete(self, path):
        if "WALK_REMOVE_CMD" in os.environ:
            cmd=os.environ["WALK_REMOVE_CMD"]
            try:
                subprocess.run([cmd, path], stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                pass
            return
        try:
            stt=os.lstat(path)
            if stat.S_ISDIR(stt.st_mode):
                import shutil; shutil.rmtree(path)
            else:
                os.unlink(path)
        except Exception:
            pass
    def delete_all_pending(self):
        for p in self.pending:
            self._actual_delete(p.entry.fullpath)
        self.pending=[]
    # ----- misc actions -----
    def press_yank(self):
        cur=self.current()
        if cur is None:
            return
        path=cur.fullpath
        # xclip first, then xsel (atotto/clipboard order on Linux)
        import shutil
        try:
            if shutil.which("xclip"):
                subprocess.run(["xclip","-in","-selection","clipboard"], input=path.encode(), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            elif shutil.which("xsel"):
                subprocess.run(["xsel","--input","--clipboard"], input=path.encode(), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        except Exception:
            pass
        self.status_text=f"copied: {path}"
        self.status_red=False

